---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Pricing cards: Three plans with a billing switch and a seat slider.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change pricing-cards.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './pricing-cards.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" draws it in the Soft style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft") */
  'data-style'?: 'soft';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', 'wide', className]} data-c="pricing-cards" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="pcx">
  <div class="pcx-top"><div class="seg2 pcx-per" role="group" aria-label="Billing"><button aria-pressed="false" data-v="m">Monthly</button><button aria-pressed="true" data-v="y">Yearly <span class="tag ok">−20%</span></button></div>
    <label class="pcx-seats"><span class="muted">Editors</span><input type="range" min="1" max="50" value="5" aria-label="Editors"><b class="num pcx-sn">5</b></label></div>
  <div class="pcx-grid"></div>
</div>
  </Fragment></div>
</div>
<script>
  import './pricing-cards.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Pricing cards ---------- */
.pcx{display:flex;flex-direction:column;gap:14px;width:100%}
.pcx-top{display:flex;align-items:center;justify-content:space-between;gap:var(--dm-s-3);flex-wrap:wrap}
.pcx-per button{font-size:12.5px;height:30px;padding:0 var(--dm-s-3);display:inline-flex;align-items:center;gap:6px}
.pcx-per .tag{height:18px;font-size:10.5px;padding:0 5px}
.pcx-seats{display:flex;align-items:center;gap:10px;font-size:12.5px}
.pcx-seats input{width:150px;accent-color:var(--dm-accent)}
.pcx-seats b{width:22px;font-weight:500}
.pcx-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:var(--dm-s-3)}
@media (max-width:760px){.pcx-grid{grid-template-columns:1fr}}
.pcx-c{padding:18px;display:flex;flex-direction:column;gap:var(--dm-s-3);transition:transform .45s var(--dm-ease),box-shadow .3s;position:relative}
@media (hover:hover) and (pointer:fine){.pcx-c:hover{box-shadow:var(--dm-shadow-pop)}}
.pcx-c.hot{box-shadow:0 0 0 1.5px var(--dm-accent-mark,var(--dm-accent)),var(--dm-shadow)}
@media (hover:hover) and (pointer:fine){.pcx-c.hot:hover{box-shadow:0 0 0 1.5px var(--dm-accent-mark,var(--dm-accent)),var(--dm-shadow-pop)}}
.pcx-c .bd{position:absolute;top:16px;right:16px}
.pcx-c .nm{font-size:14px;font-weight:500}
.pcx-c .ds{font-size:12.5px;color:var(--dm-muted);margin-top:-8px}
.pcx-pr{display:flex;flex-wrap:wrap;align-items:baseline;gap:0 6px}
.pcx-pr b{font-size:14px;font-weight:500;letter-spacing:-.02em}
.pcx-pr span{flex-basis:100%;min-height:18px;font-size:12px;color:var(--dm-muted)}
.pcx-pr s{font-size:13px;color:var(--dm-muted)}
.pcx-tot{font-size:12px;color:var(--dm-fg2);min-height:16px}
.pcx-li{display:flex;flex-direction:column;gap:7px;font-size:13px;color:var(--dm-fg2);margin:var(--dm-s-1) 0}
.pcx-li span{display:flex;align-items:center;gap:var(--dm-s-2)}
.pcx-li svg{color:var(--dm-accent-fg,var(--dm-accent));flex:none}
.pcx-c .pill{width:100%;height:38px;margin-top:auto}
/* only the recommended plan's button is the accent; the others are white with a grey outline */
.pcx-c .pill.line{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-rail) 50%,transparent)}
@media (hover:hover) and (pointer:fine){.pcx-c .pill.line:hover{background:var(--dm-wash);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-faint) 50%,transparent)}}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, DM, I, seg, stagger, swap, tween } from '../core/core.js';
DM.def('pricing-cards', (r, c) => {
  const P = [
    { n:'Starter', d:'For trying the agent', m:0, f:['1 project','50 agent runs a month','Figma import'], cta:'Start free' },
    { n:'Pro', d:'For growing design teams', m:24, f:['Unlimited projects','1,000 runs per editor','Shared tokens and memory','Priority models'], cta:'Start free trial', hot:1 },
    { n:'Enterprise', d:'For design orgs', m:null, f:['SSO and audit log','Custom spend caps','Dedicated support'], cta:'Talk to us' }
  ];
  const grid = $('.pcx-grid', r), rng = $('.pcx-seats input', r), sn = $('.pcx-sn', r);
  let per = 'y', seats = 5; const shown = P.map(() => 0);
  grid.innerHTML = P.map(p => `<div class="pcx-c panel${p.hot ? ' hot' : ''}">${p.hot ? '<span class="tag b bd">Most popular</span>' : ''}<span class="nm">${p.n}</span><span class="ds">${p.d}</span><div class="pcx-pr"><b class="num"></b><s class="num"></s><span></span></div><div class="pcx-tot num"></div><div class="pcx-li">${p.f.map(x => `<span>${I('check','xs')}${x}</span>`).join('')}</div><button class="pill ${p.hot ? 'primary' : 'line'}">${p.cta}</button></div>`).join('');
  const cards = $$('.pcx-c', grid);
  // the outlined card is the recommended one, and only its button is primary
  const ctas = () => cards.forEach(el => { const b = $('.pill', el), on = el.classList.contains('hot'); b.classList.toggle('primary', on); b.classList.toggle('line', !on); });
  function upd(){
    P.forEach((p, i) => { const el = cards[i], b = $('.pcx-pr b', el), s = $('.pcx-pr s', el), u = $('.pcx-pr span', el), tt = $('.pcx-tot', el);
      if (p.m === null){ b.textContent = 'Custom'; s.textContent = ''; u.textContent = 'billed yearly'; tt.textContent = 'Volume pricing from 25 editors'; return; }
      const unit = per === 'y' ? p.m * .8 : p.m;
      const go = () => tween(shown[i], unit, 500, v => { shown[i] = v; b.textContent = '$' + (Number.isInteger(unit) ? Math.round(v) : v.toFixed(2)); });
      // the first time, the prices count up once the cards are in view
      if (first){ b.textContent = '$0'; c.later(260, go); } else go();
      s.textContent = per === 'y' && p.m ? '$' + p.m : ''; u.textContent = p.m ? 'per editor, per month' : 'forever';
      swap(tt, p.m ? `$${(unit * seats * (per === 'y' ? 12 : 1)).toLocaleString('en-US', { maximumFractionDigits:0 })} ${per === 'y' ? 'billed yearly' : 'a month'} for ${seats} editor${seats > 1 ? 's' : ''}` : 'Up to 2 editors'); });
  }
  seg($('.pcx-per', r), v => { per = v; upd(); });
  rng.oninput = () => { seats = +rng.value; sn.textContent = seats; P.forEach((p, i) => { if (!p.m) return; const tt = $('.pcx-tot', cards[i]); const unit = per === 'y' ? p.m * .8 : p.m; tt.textContent = `$${(unit * seats * (per === 'y' ? 12 : 1)).toLocaleString('en-US', { maximumFractionDigits:0 })} ${per === 'y' ? 'billed yearly' : 'a month'} for ${seats} editor${seats > 1 ? 's' : ''}`; });
    cards[2].classList.toggle('hot', seats >= 25); cards[1].classList.toggle('hot', seats < 25); ctas(); };
  let first = true; stagger(cards, 80); upd(); first = false;
  // once in view it shows the switch at work: monthly, then back to yearly. Touching it takes over
  const flip = v => $(`.pcx-per button[data-v="${v}"]`, r).click();
  c.auto(1900, () => flip('m')); c.auto(3900, () => flip('y'));
});
